-- 通用容器: 简易的 大顶堆 / 小顶堆
-- (重复元素之间的顺序不做保证)
-- 元素比大小函数 需要自己传入



---@class SortedHeap
local SortedHeap = Class('SortedHeap')
-- 外部访问时使用:
-- local SortedHeap = import('Game.DreamSpace.Tools.SortedHeap')


-- ========================================================

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Transform = CS.UnityEngine.Transform
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


-- ========================================================

function SortedHeap:__init( capacity_, compairFunc_)

    self._capacity = capacity_ -- todo: 目前无用, 未来考虑把 数组 _datas 做成固定大小的
    self._count = 0
    self._datas = {} -- 模仿 c数组

    -- 元素比较函数 compairFunc(a,b): 当 a 优先于 b 时, 算法中需要交换
    assert( type(compairFunc_) == "function" )
    self.compairFunc = compairFunc_
end


function SortedHeap:__delete()
    self._datas = nil
end


-- =========================================== Self ================================================ --


function SortedHeap:Count()
    return self._count
end


function SortedHeap:Add( val_ )

    self._count = self._count + 1
    table.insert( self._datas, val_ )
    ---
    local i = self._count - 1
    local p = (i - 1) // 2

    while (i > 0) and self.compairFunc(self._datas[i+1], self._datas[p+1]) do 

        self:Swap( i+1, p+1 )
        ---
        i = p
        p = (i - 1) // 2
    end
end


-- 访问堆顶元素, 堆空返回 nil
function SortedHeap:PeekTop()
    return (self._count>0) and (self._datas[1]) or (nil)
end


-- 取出堆顶元素, 并重排序堆
function SortedHeap:PopTop()

    -- 得到堆顶元素, 堆尾元素放堆顶(变现删除堆尾元素)
    local top = self._datas[1]
    self._datas[1] = self._datas[self._count]
    self._datas[self._count] = nil
    self._count = self._count - 1

    local i = 0
    local l = 0
    local r = 0
    local tgtI = 0
    local lVal = 0
    local rVal = 0

    while self._count > 2*i do
        l = 2*i + 1
        r = 2*i + 2
        --
        if l > self._count-1 then 
            break
        end

        if r > self._count-1 then 
            tgtI = l
        else
            tgtI = self.compairFunc(self._datas[l+1], self._datas[r+1]) and l or r
        end

        if self.compairFunc( self._datas[i+1], self._datas[tgtI+1] ) then 
            break
        end

        self:Swap( i+1, tgtI+1 )
        i = tgtI
    end
    ---
    return top
end



function SortedHeap:Swap( idx1_, idx2_ )
    local tmp = self._datas[idx1_]
    self._datas[idx1_] = self._datas[idx2_]
    self._datas[idx2_] = tmp
end



-- for debug:
function SortedHeap:PrintAll( printElementFunc_ )
    local log = "SortedHeap: \n capacity:" .. self._capacity .. ", \n count:" .. self._count .. 
                ", \n ------------- "

    for i=1,self._count do 
        local k = i-1 
        local v = self._datas[i]
        local vStr = (printElementFunc_==nil) and tostring(v) or printElementFunc_(v)
        log = log .. "\n    k:" .. k .. ", v: " .. vStr
    end 
    print( log )
end




return SortedHeap
